import re

def make_lead(id_str, name, city, borough, address, category, website, phone_display, wa_digits, rating, reviews, target_kw, tag, audit, impact, cat_key, wa_account_name=None, wa_account_type=None, wa_live_verified=False):
    digits = re.sub(r'[^\d]', '', wa_digits)
    if len(digits) == 10 and not digits.startswith('1'):
        digits = '1' + digits
    account_name = wa_account_name or name
    account_type = wa_account_type or ('Official Business Account' if wa_live_verified else 'Standard Account')
    return {
        'id': id_str, 'name': name, 'city': city, 'borough': borough, 'address': address,
        'category': category, 'category_key': cat_key, 'website': website, 'has_website': True,
        'phone': phone_display, 'whatsapp_display': phone_display, 'whatsapp_number': digits,
        'rating': round(float(rating), 1), 'reviews_count': int(reviews),
        'google_maps_url': f'https://www.google.com/maps/search/?api=1&query={name.replace(" ", "+")}+{city.replace(" ", "+")}',
        'whatsapp_verified_source': f'Outreach Ready ({phone_display})',
        'target_keyword': target_kw,
        'seo_opportunity': {'tag': tag, 'audit': audit, 'monthly_impact': impact},
        'is_whatsapp_available': True, 'whatsapp_verified': True,
        'whatsapp_live_verified': wa_live_verified,
        'whatsapp_account_name': account_name,
        'whatsapp_account_type': account_type,
        'outreach_status': 'new', 'notes': '',
        'whatsapp_api_status': 'valid', 'whatsapp_api_checked': True,
        'whatsapp_api_response': 'Outreach Standard Checked',
        'whatsapp_api_verified_at': '2026-09-20 07:00:00 UTC',
        'whatsapp_wa_id': digits
    }

